#include <iostream>
#include <cstdio>
#include <vector>
#include <queue>
#include <climits>
using namespace std;

const int MAXN = 20;
const int MAXNODES = 2020;
const int INF = 3010;

vector<int> adj[MAXNODES];
int dist[MAXNODES];
int match[MAXNODES];
int dist_to_boundary[MAXN][MAXN], cell_capacity[MAXN][MAXN], enemy_cell[MAXN][MAXN];
char grid_s[MAXN][MAXN], grid_p[MAXN][MAXN];
int dd[MAXN][MAXN];
const int dx[4] = {0, 1, -1, 0};
const int dy[4] = {1, 0, 0, -1};
vector<int> src_pool[MAXN][MAXN], dst_pool[MAXN][MAXN];

inline void connect(int u, int v) {
    adj[u].push_back(v);
    adj[v].push_back(u);
}

int src_cnt, dst_cnt;

bool bfs_level() {
    queue<int> q;
    fill(dist, dist + src_cnt + 1, INF);
    for (int i = 1; i <= src_cnt; ++i) {
        if (match[i] == 0) {
            dist[i] = 0;
            q.push(i);
        }
    }
    dist[0] = INF;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (dist[u] < dist[0]) {
            for (int v_node : adj[u]) {
                int v = match[v_node];
                if (dist[v] == INF) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
    }
    return dist[0] != INF;
}

bool dfs_path(int u) {
    if (u == 0) return true;
    for (int v_node : adj[u]) {
        int v = match[v_node];
        if (dist[v] == dist[u] + 1) {
            if (dfs_path(v)) {
                match[u] = v_node;
                match[v_node] = u;
                return true;
            }
        }
    }
    return false;
}

int compute_max_matching() {
    int result = 0;
    while (bfs_level()) {
        for (int i = 1; i <= src_cnt; ++i) {
            if (match[i] == 0 && dfs_path(i)) {
                ++result;
            }
        }
    }
    return result;
}

int main() {
    int n, t;
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            dist_to_boundary[i][j] = t;
    for (int i = 1; i <= n; ++i)
        scanf("%s", grid_s[i] + 1);
    for (int i = 1; i <= n; ++i)
        scanf("%s", grid_p[i] + 1);
    int rx = 0, ry = 0;
    src_cnt = 1, dst_cnt = 1000;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid_s[i][j] == 'Z' || grid_s[i][j] == 'Y') {
                enemy_cell[i][j] = -1;
                dist_to_boundary[i][j] = 0;
            }
            if (grid_s[i][j] == 'Z') {
                rx = i; ry = j;
                dist_to_boundary[i][j] = 0;
            }
            if (grid_s[i][j] >= '0' && grid_s[i][j] <= '9') {
                enemy_cell[i][j] = grid_s[i][j] - '0';
                for (int k = 0; k < enemy_cell[i][j]; ++k)
                    src_pool[i][j].push_back(src_cnt++);
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (grid_p[i][j] >= '0' && grid_p[i][j] <= '9') {
                cell_capacity[i][j] = grid_p[i][j] - '0';
                for (int k = 0; k < cell_capacity[i][j]; ++k)
                    dst_pool[i][j].push_back(dst_cnt++);
            }
        }
    }
    queue<pair<int, int> > q;
    q.push(make_pair(rx, ry));
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (dist_to_boundary[nx][ny] > dist_to_boundary[x][y] + 1 && enemy_cell[nx][ny] != -1) {
                dist_to_boundary[nx][ny] = dist_to_boundary[x][y] + 1;
                q.push(make_pair(nx, ny));
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (enemy_cell[i][j] > 0) {
                for (int x = 1; x <= n; ++x)
                    for (int y = 1; y <= n; ++y)
                        dd[x][y] = 100000;
                queue<pair<int, int> > dq;
                dd[i][j] = 0;
                dq.push(make_pair(i, j));
                while (!dq.empty()) {
                    int x = dq.front().first, y = dq.front().second;
                    dq.pop();
                    for (int src_id : src_pool[i][j]) {
                        for (int dst_id : dst_pool[x][y]) {
                            connect(src_id, dst_id);
                        }
                    }
                    if (dd[x][y] == dist_to_boundary[x][y]) continue;
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (enemy_cell[nx][ny] != -1 && dd[nx][ny] > dd[x][y] + 1 && dd[x][y] + 1 <= dist_to_boundary[nx][ny]) {
                            dd[nx][ny] = dd[x][y] + 1;
                            dq.push(make_pair(nx, ny));
                        }
                    }
                }
            }
        }
    }
    printf("%d", compute_max_matching());
    return 0;
}
